define({"topics":[{"title":"Doing the power supply data diagnostic","shortdesc":"<p class=\"shortdesc\">This diagnostic reads the power supply information from the Driver Control Board (DCB) board every five seconds for the specified test duration (maximum of 300 seconds).<\/p>","href":"c_Power-Supply-Data_12457816.html","attributes":{"data-id":"id_15666838"},"menu":{"hasChildren":false},"tocID":"id_15666838-d46e45881","topics":[]},{"title":"Doing the I\/O status diagnostic","shortdesc":"<p class=\"shortdesc\">This test shows the status of the listed circuits internal to the driver module.<\/p>","href":"c_IO-Status_12457811.html","attributes":{"data-id":"id_15666837"},"menu":{"hasChildren":false},"tocID":"id_15666837-d46e45986","topics":[]},{"title":"Doing the gather load data diagnostic","shortdesc":"<p class=\"shortdesc\">This test checks the current draw on the dynamic disable (DD) and transmit\/receive (TR) bias lines. Run this test to troubleshoot intermittent problems and collect baseline data on any new surface coil.<\/p>","href":"r_diag_Gather-Load-Data-Diagnostic_14242844.html","attributes":{"data-id":"id_15667067"},"menu":{"hasChildren":false},"tocID":"id_15667067-d46e46090","topics":[]}]});